const input = $input.first().json;
const body = input.body || input;
const jobId = body.job_id;

if (!jobId || typeof jobId !== 'string' || !/^job_[a-zA-Z0-9_-]+$/.test(jobId)) {
  throw new Error('INVALID_JOB_ID: Missing or invalid job_id in webhook payload');
}

const storageDir = $env.JOB_STORAGE_DIR || '/data/jobs';
const jobDir = `${storageDir}/${jobId}`;

const jobProcessing = {
  job_id: jobId,
  status: 'processing'
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    target_file: `${jobDir}/job.json`
  },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(jobProcessing, null, 2), 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'job.json'
    }
  }
}];

const binary = $input.first().binary;
const json = $input.first().json;

const jobInfo = $('Validate Job & Paths').first().json;
const jobId = jobInfo.job_id;
const jobDir = jobInfo.job_dir;

if (!binary || !binary.data || !binary.data.data) {
  throw new Error('INVALID_AUDIO: audio.webm is missing or unreadable');
}

if (json.fileSize !== undefined && json.fileSize <= 0) {
  throw new Error('INVALID_AUDIO: audio.webm is empty');
}

const audioBinary = binary.data;

const jobTranscribing = {
  job_id: jobId,
  status: 'transcribing'
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    target_file: `${jobDir}/job.json`
  },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(jobTranscribing, null, 2), 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'job.json'
    },
    audio: audioBinary
  }
}];

const deepgram = $input.first().json;
const jobInfo = $('Validate Job & Paths').first().json;
const jobId = jobInfo.job_id;
const jobDir = jobInfo.job_dir;

if (!deepgram || !deepgram.results) {
  throw new Error('TRANSCRIPTION_FAILED: Invalid or empty Deepgram response');
}

const segments = [];
const speakerSet = new Set();

if (Array.isArray(deepgram.results.utterances) && deepgram.results.utterances.length > 0) {
  for (const u of deepgram.results.utterances) {
    const speakerNum = (u.speaker !== undefined) ? u.speaker : (u.channel !== undefined ? u.channel : 0);
    const speakerId = `speaker_${Number(speakerNum) + 1}`;
    speakerSet.add(speakerId);

    segments.push({
      speaker_id: speakerId,
      start: Math.round(Number(u.start || 0) * 100) / 100,
      end: Math.round(Number(u.end || 0) * 100) / 100,
      text: (u.transcript || '').trim()
    });
  }
} else if (Array.isArray(deepgram.results.channels)) {
  deepgram.results.channels.forEach((ch, chIdx) => {
    const alt = ch.alternatives?.[0];
    if (!alt) return;

    if (Array.isArray(alt.paragraphs?.paragraphs) && alt.paragraphs.paragraphs.length > 0) {
      for (const p of alt.paragraphs.paragraphs) {
        const speakerNum = (p.speaker !== undefined) ? p.speaker : chIdx;
        const speakerId = `speaker_${Number(speakerNum) + 1}`;
        speakerSet.add(speakerId);

        segments.push({
          speaker_id: speakerId,
          start: Math.round(Number(p.start || 0) * 100) / 100,
          end: Math.round(Number(p.end || 0) * 100) / 100,
          text: (p.sentences?.map(s => s.text).join(' ') || '').trim()
        });
      }
    } else if (Array.isArray(alt.words) && alt.words.length > 0) {
      let currentSeg = null;
      for (const w of alt.words) {
        const speakerNum = (w.speaker !== undefined) ? w.speaker : chIdx;
        const speakerId = `speaker_${Number(speakerNum) + 1}`;
        speakerSet.add(speakerId);

        if (!currentSeg || currentSeg.speaker_id !== speakerId) {
          if (currentSeg && currentSeg.text.length > 0) segments.push(currentSeg);
          currentSeg = {
            speaker_id: speakerId,
            start: Math.round(Number(w.start || 0) * 100) / 100,
            end: Math.round(Number(w.end || 0) * 100) / 100,
            text: w.punctuated_word || w.word
          };
        } else {
          currentSeg.end = Math.round(Number(w.end || 0) * 100) / 100;
          currentSeg.text += ' ' + (w.punctuated_word || w.word);
        }
      }
      if (currentSeg && currentSeg.text.length > 0) segments.push(currentSeg);
    } else if (alt.transcript && alt.transcript.trim().length > 0) {
      const speakerId = `speaker_${chIdx + 1}`;
      speakerSet.add(speakerId);
      segments.push({
        speaker_id: speakerId,
        start: 0,
        end: 0,
        text: alt.transcript.trim()
      });
    }
  });
}

segments.sort((a, b) => a.start - b.start);

if (speakerSet.size === 0) {
  speakerSet.add('speaker_1');
}

const speakers = Array.from(speakerSet).sort().map(id => {
  const num = id.replace('speaker_', '');
  return {
    speaker_id: id,
    label: `Speaker ${num}`
  };
});

if (!Array.isArray(segments)) {
  throw new Error('TRANSCRIPTION_FAILED: Transcript normalization failed');
}

const jobAnalyzing = {
  job_id: jobId,
  status: 'analyzing'
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    speakers: speakers,
    transcript: segments,
    target_file: `${jobDir}/job.json`
  },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(jobAnalyzing, null, 2), 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'job.json'
    }
  }
}];

const input = $input.first().json;
const jobId = input.job_id;
const jobDir = input.job_dir;
const speakers = input.speakers;
const transcript = input.transcript;

const transcriptFormatted = transcript.map(s => {
  const spk = speakers.find(sp => sp.speaker_id === s.speaker_id);
  const label = spk ? spk.label : s.speaker_id;
  return `[${s.speaker_id} (${label})]: ${s.text}`;
}).join('\n');

const promptText = `You are an expert AI meeting intelligence analyzer.\nAnalyze the following meeting transcript and extract structured meeting intelligence.\n\nCRITICAL RULES:\n1. summary: A concise, accurate summary of the meeting discussion.\n2. decisions: An array of concrete decisions agreed upon by the participants.\n3. action_items: An array of action items.\n   - task: The specific task description.\n   - owner: The stable speaker_id (e.g., "speaker_1", "speaker_2") of the person assigned or responsible. If not clearly determinable from the transcript, you MUST set owner to null. NEVER guess or invent names.\n   - deadline: A normalized ISO date string (YYYY-MM-DD) if a date was agreed, or null if unknown. NEVER invent dates.\n   - priority: Exactly one of "low", "medium", or "high".\n\nValid speaker IDs in this meeting:\n${JSON.stringify(speakers, null, 2)}\n\nTranscript:\n${transcriptFormatted}`;

const geminiPayload = {
  contents: [
    {
      parts: [
        {
          text: promptText
        }
      ]
    }
  ],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        summary: { type: 'STRING' },
        decisions: {
          type: 'ARRAY',
          items: { type: 'STRING' }
        },
        action_items: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              task: { type: 'STRING' },
              owner: { type: 'STRING', nullable: true },
              deadline: { type: 'STRING', nullable: true },
              priority: { type: 'STRING', enum: ['low', 'medium', 'high'] }
            },
            required: ['task', 'owner', 'deadline', 'priority']
          }
        }
      },
      required: ['summary', 'decisions', 'action_items']
    }
  }
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    speakers: speakers,
    transcript: transcript,
    geminiPayload: geminiPayload
  }
}];

const geminiRes = $input.first().json;
const prepData = $('Format Prompt & Gemini Payload').first().json;
const jobId = prepData.job_id;
const jobDir = prepData.job_dir;
const speakers = prepData.speakers;
const transcript = prepData.transcript;

const text = geminiRes.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) {
  throw new Error('ANALYSIS_FAILED: Empty response from Gemini');
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('INVALID_ANALYSIS_RESULT: Gemini output was not valid JSON');
}

if (!parsed.summary || typeof parsed.summary !== 'string') {
  throw new Error('INVALID_ANALYSIS_RESULT: MeetingData.summary must be a non-empty string');
}

if (!Array.isArray(parsed.decisions)) {
  throw new Error('INVALID_ANALYSIS_RESULT: MeetingData.decisions must be an array');
}

if (!Array.isArray(parsed.action_items)) {
  throw new Error('INVALID_ANALYSIS_RESULT: MeetingData.action_items must be an array');
}

const validSpeakerIds = new Set(speakers.map(s => s.speaker_id));
const validPriorities = new Set(['low', 'medium', 'high']);

const normalizedActionItems = parsed.action_items.map(item => {
  if (!item.task || typeof item.task !== 'string') {
    throw new Error('INVALID_ANALYSIS_RESULT: ActionItem.task is required');
  }

  let owner = item.owner;
  if (typeof owner === 'string') {
    owner = owner.trim();
    if (!validSpeakerIds.has(owner)) {
      const matchingSpeaker = speakers.find(s => s.label.toLowerCase() === owner.toLowerCase());
      owner = matchingSpeaker ? matchingSpeaker.speaker_id : null;
    }
  } else {
    owner = null;
  }

  let deadline = (typeof item.deadline === 'string' && item.deadline.trim().length > 0)
    ? item.deadline.trim()
    : null;

  let priority = item.priority;
  if (!validPriorities.has(priority)) {
    priority = 'medium';
  }

  return {
    task: item.task.trim(),
    owner: owner,
    deadline: deadline,
    priority: priority
  };
});

const meetingResult = {
  speakers: speakers,
  transcript: transcript,
  meeting: {
    summary: parsed.summary.trim(),
    decisions: parsed.decisions.map(d => String(d).trim()),
    action_items: normalizedActionItems
  }
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    meetingResult: meetingResult
  },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(meetingResult, null, 2), 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'result.json'
    }
  }
}];

const input = $('Validate MeetingData & Assemble Result').first().json;
const jobId = input.job_id;
const jobDir = input.job_dir;

const jobCompleted = {
  job_id: jobId,
  status: 'completed'
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    target_file: `${jobDir}/job.json`
  },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(jobCompleted, null, 2), 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'job.json'
    }
  }
}];

const items = $input.all();
let incomingError = null;
for (const item of items) {
  if (item.json?.error) {
    incomingError = item.json.error;
    break;
  }
}

let jobId = 'unknown';
let jobDir = '/data/jobs/unknown';
try {
  const v = $('Validate Job & Paths').first().json;
  jobId = v.job_id || jobId;
  jobDir = v.job_dir || jobDir;
} catch (e) {}

let errorCode = 'PROCESSING_FAILED';
let errorMessage = 'An error occurred while processing the meeting.';

const errStr = String(incomingError?.message || incomingError || '');

if (errStr.includes('INVALID_JOB_ID')) {
  errorCode = 'INVALID_AUDIO';
  errorMessage = 'Invalid job reference.';
} else if (errStr.includes('INVALID_AUDIO') || errStr.includes('audio.webm') || errStr.includes('No file')) {
  errorCode = 'INVALID_AUDIO';
  errorMessage = 'Meeting audio file is missing, empty, or unreadable.';
} else if (errStr.includes('TRANSCRIPTION_FAILED') || errStr.includes('deepgram') || errStr.includes('Deepgram')) {
  errorCode = 'TRANSCRIPTION_FAILED';
  errorMessage = 'We were unable to transcribe the meeting audio.';
} else if (errStr.includes('ANALYSIS_FAILED') || errStr.includes('gemini') || errStr.includes('Gemini')) {
  errorCode = 'ANALYSIS_FAILED';
  errorMessage = 'We were unable to complete the meeting analysis.';
} else if (errStr.includes('INVALID_ANALYSIS_RESULT')) {
  errorCode = 'INVALID_ANALYSIS_RESULT';
  errorMessage = 'The meeting analysis result was invalid or malformed.';
}

const jobFailed = {
  job_id: jobId,
  status: 'failed',
  error: {
    code: errorCode,
    message: errorMessage
  }
};

return [{
  json: {
    job_id: jobId,
    job_dir: jobDir,
    target_file: `${jobDir}/job.json`
  },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(jobFailed, null, 2), 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'job.json'
    }
  }
}];
